import ast, re, sys, glob, os
import exrex

def literals(node):
    out = []
    for n in ast.walk(node):
        if isinstance(n, ast.Constant) and isinstance(n.value, str):
            out.append(n.value)
    return out

def col(node):
    # find attribute names used e.g. transactions.description
    cols = set()
    for n in ast.walk(node):
        if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name) and n.value.id == "transactions":
            cols.add(n.attr)
    return cols

def sample(pat):
    p = pat
    # strip lookaheads which exrex can't handle
    p = re.sub(r"\(\?![^)]*\)", "", p)
    try:
        s = exrex.getone(p, limit=3)
    except Exception:
        return None
    return s

def analyse(path):
    src = open(path).read()
    tree = ast.parse(src)
    blocks = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and getattr(node.targets[0], "id", None) == "conditions_choices":
            if isinstance(node.value, ast.List):
                items = []
                for el in node.value.elts:
                    if isinstance(el, ast.List) and len(el.elts) == 2:
                        cond, choice = el.elts
                        items.append((el.lineno, literals(cond), col(cond), ast.unparse(choice)[:70]))
                blocks.append((node.lineno, items))
    res = []
    for bl, items in blocks:
        for j in range(len(items)):
            lj, litj, colj, chj = items[j]
            if "description" not in colj:
                continue
            for i in range(j):
                li, liti, coli, chi = items[i]
                if "description" not in coli:
                    continue
                for pj in litj:
                    if len(pj) < 4:
                        continue
                    s = sample(pj)
                    if not s:
                        continue
                    for pi in liti:
                        if len(pi) < 4:
                            continue
                        try:
                            if re.search(pi, s, re.IGNORECASE):
                                res.append((os.path.basename(path), li, lj, pi[:60], pj[:60], chi[:40], chj[:40]))
                        except re.error:
                            pass
    return res

for f in sorted(glob.glob("/app/categorizationapp/categorizationapp/BankScripts/*.py")):
    r = analyse(f)
    if r:
        print("=" * 30, os.path.basename(f))
        for row in r:
            print(f"  L{row[1]} shadows L{row[2]} | earlier=/{row[3]}/ -> {row[5]} | later=/{row[4]}/ -> {row[6]}")

